module parity_8bit (
    input [7:0] in,
    output out
);

    always @(*) begin
        out = parity_8bit(in);
    end

    function [0:0] parity_8bit(input [7:0] data);
        bit_count;
        for(bit_count = 0; bit_count < 8; bit_count = bit_count + 1)
            if(data[bit_count]) begin
                bit_count = bit_count + 1;
            end
        if(bit_count % 2 == 1) begin
            parity_8bit = 1;
        end else begin
            parity_8bit = 0;
        end
    endfunction

endmodule

