typedef enum bit [1:0] = (0'b00 : S1, 0'b10 : S2, 0'b11 : S3);
reg [1:0] state;
reg q, qn;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= S1;
        q <= 1'b0;
        qn <= 1'b0;
    end
end

always @(posedge clk) begin
    case (state)
        S1 : q <= qn;
        S2 : q <= 1'b0;
        S3 : q <= 1'b1;
        default : q <= 1'b0;
    endcase
end

always @(q) begin
    qn <= ~q;
end

assign state = q ? S3 : (qn ? S2 : S1);

endmodule

