module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

  reg up_request_reg;
  reg down_request_reg;

  always @(posedge clk or posedge reset) begin
      if (reset) begin
          state <= 0;
          up_request_reg <= 0;
          down_request_reg <= 0;
      end else begin
          if (up_request) begin
              if (state == 0) begin
                  if (up_request_reg == 0) state <= 3'b001;
                  if (up_request_reg == 1) state <= 3'b011; // Target state
                  up_request_reg <= 0;
              end else begin
                  if (up_request_reg == 1) up_request_reg <= 0;
              end
          end else begin
              up_request_reg <= 1;
          end

          if (down_request) begin
              if (state == 0) begin
                  if (down_request_reg == 0) state <= 3'b010;
                  if (down_request_reg == 1) state <= 3'b101; // Target state
                  down_request_reg <= 0;
              end else begin
                  if (down_request_reg == 1) down_request_reg <= 0;
              end
          end else begin
              down_request_reg <= 1;
          end
      end
  end

endmodule

