module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    reg [1:0] state_reg;
    reg up_request_reg;
    reg down_request_reg;

    assign state = state_reg;

    always @(posedge clk or posedge reset) begin
        if (reset)
            state_reg <= 2'b00;
        else begin
            case (state_reg)
                2'b00: 
                    if (up_request_reg && reset != 1) state_reg <= 2'b01;
                    if (up_request_reg && up_request) state_reg <= 2'b01;
                    if (down_request_reg && reset != 1) state_reg <= 2'b00;
                    if (down_request_reg && down_request) state_reg <= 2'b00;
                break;
            2'd1: 
                if (up_request_reg) state_reg <= 2'b11;
                if (down_request_reg && reset != 1) state_reg <= 2'b10;
                if (down_request_reg && down_request) state_reg <= 2'b10;
                break;
            2'd11: 
                if (up_request_reg) state_reg <= 2'b11;
                if (down_request_reg == 1) state_reg <= 2'b10;
                if (down_request_reg) state_reg <= 2'b10;
                break;
            2'd2: 
                if (up_request_reg && reset != 1) state_reg <= 2'b11;
                    if (up_request_reg && up_request) state_reg <= 2'b10;
                    if (up_request_reg && up_request) state_reg <= 2'b00;
                    break;
            default: 
                break;
            endcase
        end
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            up_request_reg <= 1'b0;
            down_request_reg <= 1'b0;
        end
        else begin
            up_request_reg <= up_request;
            down_request_reg <= down_request;
        end
    end

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    reg [2:0] states; // Temporary state variable to avoid Latch warnings

    // State encoding
    parameter IDLE = 0b000;
    parameter UP =  0b001;
    parameter DOWN = 0b010;

    // State transition logic (simplified)
    always @(posedge clk) begin
        if (reset) begin
            states <= IDLE;
        end else begin
            if (up_request && (states == IDLE || states == DOWN)) 
                states <= UP;
            else if (down_request && (states == IDLE || states == UP)) 
                states <= DOWN;
        end
    end

    // Output assignment to match state encoding
    assign state = states[2:1];

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    reg [1:0] next_state;
    reg cnt;

    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= 2'b00;
        else
            state <= next_state[state];
    end

    warm logic_sequence:
        always @(posedge clk) begin
            if (reset)
                cnt <= 0;
            else
                cnt <= cnt + 1;
        end

    warm logic_state:
        always @(posedge clk or posedge reset) begin
            if (reset) begin
                next_state <= 2'b00;
            end else begin
                case (state)
                    2'b00: begin // Empty
                        if (item_selected) next_state <= 2'b01; // Dispense
                    end
                    2'b01: begin // Dispensing
                        if (coin_inserted) next_state <= 2'b10;
                    end
                    2'b10: begin // Paid
                        if (coin_inserted) next_state <= 2'b00;
                        else next_state <= 2'b01;
                    end
                    2'b11: begin // Dispensed
                        if (item_selected) next_state <= 2'b00;
                    end
                    default: next_state <= 2'b00;
                endcase
            end
        end

    endmodule

