    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tally <= 3'd0;
        end else begin
            if (coin_inserted == 1)
                tally <= tally + 2'b01; // chip
            if (item_selected == 1 && tally <= 2)
                tally <= tally + 2'b10; // coin
        end
    end

