module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);
    integer i;
    begin
        if (in_0 == 0) begin
            out = -1;
        end
        else begin
            for (i = 0; i < 16; i = i + 1) begin
                if ((in_0 >> (i * 2)) == 0) begin
                    break;
                end else begin
                    in_0 = in_0 >> (2 * i);
                end
            end
            out = i + (in_0 < 0 ? 1 : 0);
        end
    end
endmodule

