    case (curr_state)
      2'b00: next_state = 2'b01;    // Start of sequence
      2'b01: next_state = 2'b10;    // Day 2
      2'b10: next_state = 2'b11;    // Day 3 (end of first 3 days)
      2'b11: next_state = 2'b00;    // Loop back to start

