  assign temp_q[0] = q[1];
  assign temp_q[1] = q[2];
  assign temp_q[2] = q[3];
  assign temp_q[3] = q[0];

  // Flip-flop for temp_q
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      temp_q <= 4'b0000;
    end else begin
      if (load) begin
        temp_q <= q;
