  input b,
  input c,
  input d,
  output q
);

  wire b_not = ~b;
  wire c_not = ~c;
  wire a_not = ~a;

  wire gate_b_and_a = (a & b);
  wire gate_b_and_not_a = (b & a_not);
  wire gate_c_and_not_b = (c & b_not);
  wire gate_c_and_not_a = (c & a_not);
  wire gate_a_and_not_c = (a & c_not);
  wire gate_b_and_c = (b & c);

