  wire gate_j = (c_not_b && c_not_a);
  wire gate_k = (c_not_b && a_and_not_c);
  wire gate_l = (c_not_a && b_and_gate_c);
  wire gate_n = (a & c_not);
  wire gate_o = (b_not && a_and_not_c);

  wire output_gate_m = (gate_i && gate_c_and_not_a);
  wire output_gate_p = (gate_j || gate_k || gate_l || gate_n || gate_o);

  assign q = output_gate_p;
