    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

always @(*) begin
    // Perform binary addition
    [7:0] temp = {B[3:0], A[3:0], Cin};

    // Trim to 4 bits if no carry out from full adder
    if (temp[7] | temp[6] | temp[5] | temp[4]) begin
        Cout = 1;
        // Decode to BCD
        case (temp[3:0])
            0: Begin_sum = 0;
            1: Begin_sum = 1;
            2: Begin_sum = 2;
            3: Begin_sum = 3;
            4: Begin_sum = 4;
            5: Begin_sum = 5;
            6: Begin_sum = 6;
            7: Begin_sum = 7;
            8: Begin_sum = 8;
            9: Begin_sum = 9;
            10: Begin_sum = {5'b00000, 2'b11}; // Force logic OR 10 via temp[3:0]
            11: Begin_sum = {5'b00001, 2'b01};  // Force logic OR 10 via temp[3:0]
            12: Begin_sum = {5'b00001, 2'b00};  // Force logic OR 10 via temp[3:0]
            13: Begin_sum = {5'b00001, 2'b11};  // Force logic OR 10 via temp[3:0]
            14: Begin_sum = {5'b00001, 2'b01};  // Force logic OR 10 via temp[3:0]
            15: Begin_sum = {5'b00001, 2'b00};  // Force logic OR 10 via temp[3:0]
            default: Begin_sum = 4'b0000;
        endcase
        // Correct fixation of BCD code
        if (Begin_sum[3] | Begin_sum[2]) begin
            Sum = {3'b000, Begin_sum[2]};
        else if (Begin_sum[1]) begin
            Sum = {3'b001, Begin_sum[2]};
        else if (Begin_sum[0]) begin
            Sum = {3'b010, Begin_sum[2]};
        else
            Sum = Begin_sum[1:0];
    end else begin
        Cout = 0;
        // Case when temp[3:0] is in excess decimal number range
        case (temp[3:0])
            0: Sum = 0;
            1: Sum = 1;
            2: Sum = 2;
            3: Sum = 3;
            4: Sum = 4;
            5: Sum = 5;
            6: Sum = 6;
            7: Sum = 7;
            8: Sum = 8;
            9: Sum = 9;
