            11: Sum = {5'b00010, 2'b01}; // Force logic OR 10 via temp[3:0]
            12: Sum = {5'b00010, 2'b00}; // Force logic OR 10 via temp[3:0]
            13: Sum = {5'b00010, 2'b11}; // Force logic OR 10 via temp[3:0]
            14: Sum = {5'b00010, 2'b01}; // Force logic OR 10 via temp[3:0]
            15: Sum = {5'b00010, 2'b00}; // Force logic OR 10 via temp[3:0]
            default: Sum = 4'b0000;
        endcase
    end
end

