    reg Cout_reg;
    reg [3:0] temp_sum;

    assigned Cout_reg = Cout;

    uinst1:
        assign temp_sum = A + B + Cin_reg;

    uinst2:
        assign Cin_reg = (temp_sum [0:2] > 7) || (temp_sum [0:2] > 9 && temp_sum [3] != 0);

    uinst3:
        assign Cout_reg = (temp_sum [0:2] > 9) || (temp_sum [0:2] > 9 && temp_sum [3] != 0);

