module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    wire [3:0] parallel_sum;
    wire p;
    wire k;
    wire borrow;

    // Add parallel and use conditional to get sum
    assigned (parallel_sum = A + 4 * B + 6 * Cin);
    assigned (p = A & B);
    assigned (k = (A[3] | B[3]) & (A[2:0] + B[2:0]));
    assigned (borrow = ((A + 4 * B + 6 * Cin) > 9) | ((A + 8 * B) > 9));

    // BCD Encoder
    always @(*) begin
        Sum = parallel_sum;
        if ((A + 4 * B + 6 * Cin) > 9) begin
            Sum = Sum - 10;
            Cout = 1;
        end else if ((A + 8 * B) > 9) begin
            Sum = Sum - 10;
            Cout = 1;
        end else if ((A + 4 * B + 6 * Cin) < 9) begin
            Sum = Sum + 1;
        end else begin
            Cout = 0;
        end
    end

endmodule

module adder_bcd (
