    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    assign Sum = (A + B + Cin) >= 10 ? ((A + B + Cin) - 10 + (A > 9 ? 1 : 0) + (B > 9 ? 1 : 0)) : (A + B + Cin);
    assign Cout = Sum >= 10 || (A + B + Cin) >= 16;
endmodule

